//! Complete `OpenAI` Responses replies.
//!
//! The response is generated by the shared admission and encoding path; this module decodes the
//! completion once and turns the parser's output into typed items.
use super::super::TextState;
use super::super::execution::{Prepared as Generation, parse_reply};
use super::output::{self, Snapshot, Usage};
use crate::constants::TOKEN_STAGING_BYTES;
use infer_core::{Error, ErrorCode};
use infer_ir::WorkloadOutput;
use infer_runtime::{CompletedRequest, EngineOutput};
use serde_json::Value;
use std::sync::atomic::Ordering;
use std::time::{SystemTime, UNIX_EPOCH};

/// Generate one complete response object from an already admitted generation.
///
/// # Errors
/// Returns the same backend errors as the chat route.
pub(super) async fn generate_prepared(
    state: &TextState,
    mut prepared: Generation,
    spec: &super::request::Spec,
) -> infer_core::Result<Value> {
    while let Some(event) = prepared.receiver.recv().await {
        if let EngineOutput::Finished(result) = event? {
            return respond(state, result, &prepared, spec).await;
        }
    }
    Err(Error::new(
        ErrorCode::Backend,
        "request stream closed before completion",
    ))
}

async fn respond(
    state: &TextState,
    result: CompletedRequest,
    prepared: &Generation,
    spec: &super::request::Spec,
) -> infer_core::Result<Value> {
    let Some(WorkloadOutput::Tokens(tokens)) = result.output else {
        return Err(Error::invariant("generation completed without tokens"));
    };
    let completion_tokens = tokens.len();
    let assets = state.assets.clone();
    let text = state
        .delivery
        .run(
            tokens.len().saturating_mul(TOKEN_STAGING_BYTES),
            move |_| assets.decode(&tokens, true),
        )
        .await?;
    let parsed = parse_reply(
        &text,
        prepared.dialect,
        &prepared.policy,
        prepared.enable_thinking,
        prepared.reasoning_open.load(Ordering::Acquire),
    )?;
    let (status, incomplete) = output::terminal(&result.reason, &parsed)?;
    let call_namespace = spec
        .response_id
        .clone()
        .unwrap_or_else(|| result.request.to_string());
    let output = output::items(&call_namespace, &parsed, status);
    let completed_at = (status == "completed").then(now).transpose()?;
    let usage = Usage {
        input: prepared.prompt_tokens.load(Ordering::Relaxed),
        output: completion_tokens,
        reasoning: 0,
    };
    Ok(Snapshot {
        request: result.request,
        created: prepared.created,
        completed_at,
        model: &prepared.model_name,
        status,
        incomplete,
        error: None,
        output: &output,
        spec,
        temperature: prepared.temperature,
        top_p: prepared.top_p,
        usage: Some(&usage),
    }
    .value())
}

fn now() -> infer_core::Result<u64> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .map_err(|error| Error::new(ErrorCode::Backend, error.to_string()))
}
